@msig trait PowerCommandInterlockOwner_supervisor_process_power_command_interlock_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock)
  }

  /** helper function to set the values of all input ports.
   * @param actuation_feedback payload for data port actuation_feedback
   * @param availability_decision payload for data port availability_decision
   * @param demand_view payload for data port demand_view
   * @param recovery_gate payload for data port recovery_gate
   * @param accepted_directive payload for data port accepted_directive
   */
  def put_concrete_inputs(actuation_feedback : Power_Propulsion_Availability_Supervisor.ActuationFeedback.Type,
                          availability_decision : Power_Propulsion_Availability_Supervisor.AvailabilityDecision,
                          demand_view : Power_Propulsion_Availability_Supervisor.DemandPhase.Type,
                          recovery_gate : Power_Propulsion_Availability_Supervisor.RecoveryGate.Type,
                          accepted_directive : Power_Propulsion_Availability_Supervisor.PriorityDirective.Type): Unit = {
    put_actuation_feedback(actuation_feedback)
    put_availability_decision(availability_decision)
    put_demand_view(demand_view)
    put_recovery_gate(recovery_gate)
    put_accepted_directive(accepted_directive)
  }


  /** helper function to check PowerCommandInterlockOwner_supervisor_process_power_command_interlock's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param power_command method that will be called with the value of the outgoing data
   *        port 'power_command'.
   */
  def check_concrete_output(power_command: Power_Propulsion_Availability_Supervisor.PowerCommand.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val power_commandValue: Power_Propulsion_Availability_Supervisor.PowerCommand.Type = get_power_command().get
    if(!power_command(power_commandValue)) {
      testFailures = testFailures :+ st"'power_command' did not match expected: value of the outgoing data port is ${power_commandValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_actuation_feedback(value : Power_Propulsion_Availability_Supervisor.ActuationFeedback.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.operational_api.actuation_feedback_Id, Power_Propulsion_Availability_Supervisor.ActuationFeedback_Payload(value))
  }

  // setter for in DataPort
  def put_availability_decision(value : Power_Propulsion_Availability_Supervisor.AvailabilityDecision): Unit = {
    Art.insertInInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.operational_api.availability_decision_Id, Power_Propulsion_Availability_Supervisor.AvailabilityDecision_Payload(value))
  }

  // setter for in DataPort
  def put_demand_view(value : Power_Propulsion_Availability_Supervisor.DemandPhase.Type): Unit = {
