  }

  // setter for in DataPort
  def put_accepted_directive(value : Power_Propulsion_Availability_Supervisor.PriorityDirective.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.operational_api.accepted_directive_Id, Power_Propulsion_Availability_Supervisor.PriorityDirective_Payload(value))
  }

  // getter for out DataPort
  def get_power_command(): Option[Power_Propulsion_Availability_Supervisor.PowerCommand.Type] = {
    val value: Option[Power_Propulsion_Availability_Supervisor.PowerCommand.Type] = get_power_command_payload() match {
      case Some(Power_Propulsion_Availability_Supervisor.PowerCommand_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port power_command.  Expecting 'Power_Propulsion_Availability_Supervisor.PowerCommand_Payload' but received ${v}")
      case _ => None[Power_Propulsion_Availability_Supervisor.PowerCommand.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_power_command_payload(): Option[Power_Propulsion_Availability_Supervisor.PowerCommand_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_command_interlock.initialization_api.power_command_Id).asInstanceOf[Option[Power_Propulsion_Availability_Supervisor.PowerCommand_Payload]]
